/**
 * Period and proration arithmetic shared by the renewal job and the billing
 * service's mid-period charges. Pure functions only — no repository access.
 */
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Adds `months` calendar months to `date`, clamping the day to the target
 * month's last day when the original day does not exist there — 31 Jan
 * becomes 28 (or 29) Feb, 29 Feb becomes 28 Feb a year later.
 */
function addMonthsClamped(date: Date, months: number): Date {
  const year = date.getUTCFullYear();
  const targetMonth = date.getUTCMonth() + months;
  const lastDayOfTargetMonth = new Date(
    Date.UTC(year, targetMonth + 1, 0),
  ).getUTCDate();

  return new Date(
    Date.UTC(
      year,
      targetMonth,
      Math.min(date.getUTCDate(), lastDayOfTargetMonth),
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds(),
      date.getUTCMilliseconds(),
    ),
  );
}

/**
 * The end of a new period starting at `start`. Always derived from the actual
 * start timestamp, never from an original anchor day, so a clamped day
 * carries forward period to period (28 Feb → 28 Mar, not back to 31 Mar).
 */
export function periodEndAfter(
  start: IsoTimestamp,
  interval: BillingInterval,
): IsoTimestamp {
  return toIsoTimestamp(addMonthsClamped(new Date(start), monthsInInterval(interval)));
}

/** The plan's full charge for one period at `seats`, in cents. */
export function fullPeriodChargeCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}

/** Whole days spanned by a period, rounded, at least one. */
export function daysInPeriod(start: IsoTimestamp, end: IsoTimestamp): number {
  const spanMs = new Date(end).getTime() - new Date(start).getTime();
  return Math.max(1, Math.round(spanMs / DAY_MS));
}

/** Whole-or-started days remaining to `end` as of `now`; zero once reached. */
export function daysLeftInPeriod(end: IsoTimestamp, now: Date): number {
  const remainingMs = new Date(end).getTime() - now.getTime();
  return Math.max(0, Math.ceil(remainingMs / DAY_MS));
}

/**
 * Prorates `fullChargeCents` by the days left in `[start, end)` as of `now`,
 * rounded down to whole cents.
 */
export function prorateCents(
  fullChargeCents: number,
  start: IsoTimestamp,
  end: IsoTimestamp,
  now: Date,
): number {
  const daysLeft = daysLeftInPeriod(end, now);
  if (daysLeft === 0) return 0;
  return Math.floor((fullChargeCents * daysLeft) / daysInPeriod(start, end));
}

