/**
 * A plan change ends the trial by default: the org has made a deliberate
 * choice. `options.status` overrides that — a change made mid-trial keeps
 * `trialing` — and `options.period` resets the current period, used when an
 * org leaves the free plan and starts a fresh billing cycle.
 */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
  options: {
    status?: SubscriptionStatus;
    period?: { start: IsoTimestamp; end: IsoTimestamp };
  } = {},
): Promise<Subscription> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      plan,
      interval,
      status: options.status ?? "active",
      ...(options.period === undefined
        ? {}
        : {
            currentPeriodStart: options.period.start,
            currentPeriodEnd: options.period.end,
          }),
      updatedAt: stamp,
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Advances the current period without touching plan, interval or status. */
export async function updateSubscriptionPeriod(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/**
 * A cancellation whose date has arrived: moves the workspace to the free
 * plan, clears the pending cancellation and opens a fresh monthly period.
 */
export async function applyCancellationEffect(
  orgId: OrgId,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      plan: "free",
      status: "active",
      cancelAt: null,
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

