/**
 * Feeds the billing-renewal job: every live org's `active` or `canceled`
 * subscription. Cross-tenant by design, it sweeps every workspace; archived
 * workspaces are excluded entirely rather than left for the job to skip.
 */
export async function listRenewableSubscriptions(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(
      and(
        isNull(organizations.archivedAt),
        or(eq(subscriptions.status, "active"), eq(subscriptions.status, "canceled")),
      ),
    )
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */

