/**
 * Rolls every workspace's subscription period forward past `now`, invoicing
 * each renewed paid period, and ends cancellations whose date has arrived.
 *
 * Must call (do not reimplement): emit, getPlanLimits, issueInvoice,
 * periodEndAfter, fullPeriodChargeCents
 */
import { getPlanLimits } from "@/config/plan-limits";
import { fullPeriodChargeCents, periodEndAfter } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

const FREE_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * `active` subscriptions catch up one period at a time until their period
 * end lies after `now`, invoicing every paid period along the way. `canceled`
 * subscriptions whose cancellation date has arrived move to the free plan.
 * `trialing` and `past_due` subscriptions are left for the trial-expiry job.
 * Re-running at the same instant is a no-op: once a subscription's period
 * end is past `now`, or its cancellation has already been applied, nothing
 * here matches it again.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listRenewableSubscriptions();

    for (const subscription of subscriptions) {
      try {
        if (subscription.status === "active") {
          await renew(subscription, now);
        } else if (subscription.status === "canceled") {
          await endCancellation(subscription, now);
        }
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function renew(subscription: Subscription, now: Date): Promise<void> {
  const nowMs = now.getTime();
  let periodStart = subscription.currentPeriodStart;
  let periodEnd = subscription.currentPeriodEnd;

  while (new Date(periodEnd).getTime() <= nowMs) {
    periodStart = periodEnd;
    periodEnd = periodEndAfter(periodStart, subscription.interval);

    if (subscription.plan !== FREE_PLAN) {
      const amountCents = fullPeriodChargeCents(
        getPlanLimits(subscription.plan).priceCentsPerSeatMonthly,
        subscription.seats,
        subscription.interval,
      );
      await issueInvoice(
        subscription.orgId,
        { start: periodStart, end: periodEnd },
        amountCents,
        null,
      );
    }
  }

  if (periodEnd !== subscription.currentPeriodEnd) {
    await subscriptionRepo.updateSubscriptionPeriod(
      subscription.orgId,
      periodStart,
      periodEnd,
    );
  }
}

async function endCancellation(
  subscription: Subscription,
  now: Date,
): Promise<void> {
  if (subscription.cancelAt === null) return;
  if (new Date(subscription.cancelAt).getTime() > now.getTime()) return;

  const fromPlan = subscription.plan;
  const periodStart = subscription.cancelAt;
  const periodEnd = periodEndAfter(periodStart, "monthly");

  await subscriptionRepo.applyCancellationEffect(
    subscription.orgId,
    periodStart,
    periodEnd,
  );

  await emit("billing.plan_changed", {
    orgId: subscription.orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(now),
    from: fromPlan,
    to: FREE_PLAN,
  });
}

