import { afterAll, beforeAll, describe, expect, it } from "vitest";

vi_mock_noop();
function vi_mock_noop() {}

import {
  daysInPeriod,
  daysLeftInPeriod,
  fullPeriodChargeCents,
  periodEndAfter,
  prorateCents,
} from "@/lib/billing-period";
import { subscribe } from "@/lib/event-bus";
import * as invoiceRepo from "@/server/repositories/invoice-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { runBillingRenewalJob } from "@/server/jobs/billing-renewal-job";
import * as billingService from "@/server/services/billing-service";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";
import { toIsoTimestamp } from "@/types/common";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("period math", () => {
  it("clamps month-end rollover", () => {
    expect(periodEndAfter(toIsoTimestamp(new Date("2026-01-31T10:00:00.000Z")), "monthly")).toBe(
      toIsoTimestamp(new Date("2026-02-28T10:00:00.000Z")),
    );
    expect(periodEndAfter(toIsoTimestamp(new Date("2026-02-28T10:00:00.000Z")), "monthly")).toBe(
      toIsoTimestamp(new Date("2026-03-28T10:00:00.000Z")),
    );
    expect(periodEndAfter(toIsoTimestamp(new Date("2024-02-29T10:00:00.000Z")), "annual")).toBe(
      toIsoTimestamp(new Date("2025-02-28T10:00:00.000Z")),
    );
  });

  it("prorates days left over days in period, rounded down", () => {
    const start = toIsoTimestamp(new Date("2026-03-01T00:00:00.000Z"));
    const end = toIsoTimestamp(new Date("2026-03-31T00:00:00.000Z")); // 30 days
    const now = new Date("2026-03-16T02:00:00.000Z"); // 14d22h left -> 15

    expect(daysInPeriod(start, end)).toBe(30);
    expect(daysLeftInPeriod(end, now)).toBe(15);
    expect(prorateCents(3000, start, end, now)).toBe(1500);
  });

  it("charges zero once the period end has passed", () => {
    const start = toIsoTimestamp(new Date("2026-03-01T00:00:00.000Z"));
    const end = toIsoTimestamp(new Date("2026-03-31T00:00:00.000Z"));
    const now = new Date("2026-04-01T00:00:00.000Z");
    expect(prorateCents(3000, start, end, now)).toBe(0);
  });

  it("computes the full period charge", () => {
    expect(fullPeriodChargeCents(900, 10, "monthly")).toBe(9000);
    expect(fullPeriodChargeCents(900, 10, "annual")).toBe(108000);
  });
});

describe("billing renewal job", () => {
  let tenant: Tenant;

  beforeAll(async () => {
    tenant = await createTenant("renewal-tmp", "growth");
    // Flip the trial to active without touching the stored period.
    await subscriptionRepo.cancelSubscription(tenant.org.id, null);
  });

  it("catches up multiple elapsed periods and invoices each one", async () => {
    const pastStart = toIsoTimestamp(new Date("2026-01-01T00:00:00.000Z"));
    const pastEnd = toIsoTimestamp(new Date("2026-02-01T00:00:00.000Z"));
    await subscriptionRepo.updateSubscriptionPeriod(tenant.org.id, pastStart, pastEnd);

    const now = new Date("2026-04-01T00:00:00.000Z"); // three monthly periods behind

    const invoiceEvents: unknown[] = [];
    const off = subscribe("billing.invoice_issued", (payload) => {
      invoiceEvents.push(payload);
    });

    const result = await runBillingRenewalJob(now);
    off();

    expect(result.failed).toBe(0);
    expect(invoiceEvents.length).toBe(3);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodStart).toBe(
      toIsoTimestamp(new Date("2026-04-01T00:00:00.000Z")),
