    const off = subscribe("billing.plan_changed", (payload) => events.push(payload));

    const before = await runBillingRenewalJob(new Date("2026-01-15T00:00:00.000Z"));
    const subStillPaid = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subStillPaid?.plan).toBe("starter");

    const after = await runBillingRenewalJob(new Date("2026-02-02T00:00:00.000Z"));
    const subFree = await subscriptionRepo.findSubscription(tenant.org.id);
    off();

    expect(before.failed).toBe(0);
    expect(after.failed).toBe(0);
    expect(subFree?.plan).toBe("free");
    expect(subFree?.status).toBe("active");
    expect(subFree?.cancelAt).toBe(null);
    expect(events.length).toBe(1);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(0);

    // Replay: already free + active, no second announcement.
    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));
    expect(events.length).toBe(1);
  });
});

describe("mid-period proration", () => {
  it("charges for seats added on a paid active subscription, prorated", async () => {
    const tenant = await createTenant("seats-tmp", "starter");
    await subscriptionRepo.cancelSubscription(tenant.org.id, null); // -> active
    const future = new Date(Date.now() + 1_000 * 24 * 60 * 60 * 1000); // ~2.7 years out
    const start = toIsoTimestamp(future);
    const end = toIsoTimestamp(new Date(future.getTime() + 31 * 24 * 60 * 60 * 1000)); // 31 days
    await subscriptionRepo.updateSubscriptionPeriod(tenant.org.id, start, end);
    await subscriptionRepo.updateSeatCount(tenant.org.id, 2);

    const events: unknown[] = [];
    const off = subscribe("billing.invoice_issued", (payload) => events.push(payload));

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 4,
    });
    off();

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(1);
    expect(events.length).toBe(1);
    expect(invoices[0]?.amountCents).toBeGreaterThan(0);
    expect(invoices[0]?.amountCents).toBeLessThan(1800); // prorated below the full charge for 2 seats
  });

  it("charges nothing when removing seats", async () => {
    const tenant = await createTenant("seats-tmp-2", "starter");
    await subscriptionRepo.cancelSubscription(tenant.org.id, null);
    await subscriptionRepo.updateSeatCount(tenant.org.id, 5);

    await billingService.updateSeats(tenant.actors.owner, {
      orgId: tenant.org.id,
      seats: 2,
    });

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(0);
  });

  it("charges nothing choosing a plan during a trial, and keeps the trial period", async () => {
    const tenant = await createTenant("trial-tmp", "growth"); // trialing by default
    const before = await subscriptionRepo.findSubscription(tenant.org.id);

    const updated = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    expect(updated.status).toBe("trialing");
    expect(updated.currentPeriodStart).toBe(before?.currentPeriodStart);
    expect(updated.currentPeriodEnd).toBe(before?.currentPeriodEnd);

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(0);
  });

  it("invoices in full, with a fresh period, leaving the free plan for a paid one", async () => {
    const tenant = await createTenant("free-leave-tmp", "free");

    const updated = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });

    expect(updated.status).toBe("active");
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.length).toBe(1);
    expect(invoices[0]?.amountCents).toBe(updated.seats * 900);
  });
});

